120		assertAccountState(t, n, keys[0].pub, 4, 7,
121			[]uint64{5, 6, 8, 10}, []string{"waiting-pack", "waiting-pack", "waiting-pack", "waiting-pack"})
122	
123		// 补交 7：缺口移到 9。
124		submitAll(t, n, tx7)
125		assertAccountState(t, n, keys[0].pub, 4, 9,
126			[]uint64{5, 6, 7, 8, 10},
127			[]string{"waiting-pack", "waiting-pack", "waiting-pack", "waiting-pack", "waiting-pack"})
128	
