130		submitAll(t, n, tx9)
131		assertAccountState(t, n, keys[0].pub, 4, 0,
132			[]uint64{5, 6, 7, 8, 9, 10},
133			[]string{"waiting-pack", "waiting-pack", "waiting-pack", "waiting-pack", "waiting-pack", "waiting-pack"})
134	}
135	
136	// 待处理列表同时包含等待投票与等待打包的交易：单块上限 2，补齐 5 但尚未补齐 7
137	// 时产生本地提议，序号 5、6 进入候选（waiting-vote），8、10 仍在排队
138	// （waiting-pack）；已确认序号仍为 4，缺口仍为 7——进入候选的交易不算缺失。
139	// 提议冻结后补交 7、9，缺口依次变为 9 和 0，提议仍只含 5、6。
140	// 提议确认后已确认序号推进到 6，待处理只剩 7 至 10，缺口继续为 0，
141	// 不因 5、6 已离开池中而重新报缺口 5。
142	func TestAccountGapWithProposedAndQueued(t *testing.T) {
