155	
156		// 产生本地提议：5、6 进入候选等待投票，8、10 仍等待打包。
157		// 缺口仍是 7：已确认序号 4 之后，5、6 已在候选中不算缺失。
158		p, err := n.Propose()
159		if err != nil {
160			t.Fatal(err)
161		}
162		wantProposal := []string{tx5.ID(), tx6.ID()}
163		if fmt.Sprint(p.TxIDs) != fmt.Sprint(wantProposal) {
164			t.Fatalf("proposal = %v, want %v", p.TxIDs, wantProposal)
165		}
166		assertAccountState(t, n, keys[0].pub, 4, 7,
167			[]uint64{5, 6, 8, 10},
168			[]string{"waiting-vote", "waiting-vote", "waiting-pack", "waiting-pack"})
169	
170		// 提议产生后补交 7：缺口移到 9，已冻结的提议仍只含 5、6。
171		submitAll(t, n, tx7)
172		assertAccountState(t, n, keys[0].pub, 4, 9,
173			[]uint64{5, 6, 7, 8, 10},
174			[]string{"waiting-vote", "waiting-vote", "waiting-pack", "waiting-pack", "waiting-pack"})
175		frozen, ok := n.Proposal()
176		if !ok || fmt.Sprint(frozen.TxIDs) != fmt.Sprint(wantProposal) {
177			t.Fatalf("proposal must stay frozen at %v, got %+v", wantProposal, frozen)
178		}
179	
180		// 补交 9：缺口归零，提议依旧不变。
181		submitAll(t, n, tx9)
182		assertAccountState(t, n, keys[0].pub, 4, 0,
183			[]uint64{5, 6, 7, 8, 9, 10},
184			[]string{"waiting-vote", "waiting-vote", "waiting-pack", "waiting-pack", "waiting-pack", "waiting-pack"})
185		frozen, ok = n.Proposal()
186		if !ok || fmt.Sprint(frozen.TxIDs) != fmt.Sprint(wantProposal) {
187			t.Fatalf("proposal must stay frozen at %v, got %+v", wantProposal, frozen)
188		}
189	
190		// 投票确认该提议：已确认序号推进到 6，待处理只剩 7 至 10。
191		// 缺口继续为 0，不能因为 5、6 已离开池中就重新报缺口 5。
192		round := n.CurrentRound()
193		var res *VoteResult
194		for i := 0; i < 3; i++ {
195			res, err = n.Vote(keys[i].pub, round, p.BlockID)
196			if err != nil {
197				t.Fatalf("vote %d: %v", i, err)
198			}
199		}
200		if !res.Confirmed || res.Block == nil {
201			t.Fatalf("third vote should confirm: %+v", res)
202		}
203		assertAccountState(t, n, keys[0].pub, 6, 0,
204			[]uint64{7, 8, 9, 10},
205			[]string{"waiting-pack", "waiting-pack", "waiting-pack", "waiting-pack"})
206	}
207	
208	// 边界情形：没有任何待处理交易的账户返回空列表与缺口 0；
209	// 从已确认序号加一开始连续排队、但末尾没有更多交易的账户同样返回缺口 0
210	// （末尾尚未提交的下一笔不算缺口）；全部确认完毕后回到空列表与缺口 0。
211	func TestAccountGapEmptyAndContinuous(t *testing.T) {
212		keys := genKeys(t, 4)
213		n, _ := newTestNode(t, keys, 2)
214	
215		// 从未提交过交易的账户：空列表、缺口 0、已确认序号 0。
216		assertAccountState(t, n, keys[1].pub, 0, 0, nil, nil)
217	
218		// 从已确认序号加一开始连续排队，末尾没有更多交易：缺口 0。
219		tx1 := NewTransaction(keys[0].priv, 1, []byte("one"), 1, 100)
220		tx2 := NewTransaction(keys[0].priv, 2, []byte("two"), 2, 100)
221		tx3 := NewTransaction(keys[0].priv, 3, []byte("three"), 3, 100)
222		submitAll(t, n, tx1, tx2, tx3)
223		assertAccountState(t, n, keys[0].pub, 0, 0,
224			[]uint64{1, 2, 3}, []string{"waiting-pack", "waiting-pack", "waiting-pack"})
225		// 未提交过交易的账户不受邻居影响。
226		assertAccountState(t, n, keys[1].pub, 0, 0, nil, nil)
227	
228		// 全部确认完毕后：已确认序号 3，待处理列表为空，缺口 0。
229		confirmLocalProposal(t, n, keys, []string{tx1.ID(), tx2.ID()})
230		confirmLocalProposal(t, n, keys, []string{tx3.ID()})
231		assertAccountState(t, n, keys[0].pub, 3, 0, nil, nil)
232	}
